/* Acme DS foundations: token variables, base type, and component styles.
   Components are styled only with token CSS variables. */
@import '../dist/tokens.css';

:root {
  font-family: var(--font-family-sans);
  font-size: var(--font-size-md);
  line-height: var(--font-line-height-normal);
  color: var(--color-text-primary);
  background: var(--color-surface-default);
}

/* Button */
.acme-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--button-padding-y) var(--button-padding-x);
  border: 1px solid transparent;
  border-radius: var(--button-radius);
  font: inherit;
  font-weight: var(--font-weight-medium);
  cursor: pointer;
}
.acme-button:focus-visible { outline: 2px solid var(--color-border-focus); outline-offset: 2px; }
.acme-button:disabled { cursor: not-allowed; color: var(--color-text-disabled); }
.acme-button--sm { padding: var(--space-1) var(--space-3); font-size: var(--font-size-sm); }
.acme-button--primary { background: var(--button-primary-bg); color: var(--button-primary-fg); }
.acme-button--primary:hover:not(:disabled) { background: var(--button-primary-bg-hover); }
.acme-button--secondary {
  background: var(--button-secondary-bg);
  color: var(--button-secondary-fg);
  border-color: var(--button-secondary-border);
}
.acme-button--secondary:hover:not(:disabled) { background: var(--button-secondary-bg-hover); }
.acme-button--destructive { background: var(--button-destructive-bg); color: var(--button-destructive-fg); }
.acme-button--destructive:hover:not(:disabled) { background: var(--button-destructive-bg-hover); }
.acme-button--ghost { background: transparent; color: var(--button-ghost-fg); }
.acme-button--ghost:hover:not(:disabled) { background: var(--button-ghost-bg-hover); }

/* Alert */
.acme-alert {
  padding: var(--alert-padding);
  border: 1px solid;
  border-radius: var(--alert-radius);
}
.acme-alert__title { margin: 0 0 var(--space-1); font-weight: var(--font-weight-semibold); }
.acme-alert__body { margin: 0; }
.acme-alert--success { background: var(--alert-success-bg); color: var(--alert-success-fg); border-color: var(--alert-success-border); }
.acme-alert--warning { background: var(--alert-warning-bg); color: var(--alert-warning-fg); border-color: var(--alert-warning-border); }
.acme-alert--danger { background: var(--alert-danger-bg); color: var(--alert-danger-fg); border-color: var(--alert-danger-border); }

